  "foetal-circulation": [
    { label: "Bhatt 2013 Transition Experiment", citation: "Bhatt S, Alison BJ, Wallace EM, et al. Delaying cord clamping until ventilation onset improves cardiovascular function at birth in preterm lambs. Journal of Physiology. 2013;591(8):2113–2126. Mechanistic animal study, not a human cord-clamping protocol.", url: "https://pmc.ncbi.nlm.nih.gov/articles/PMC3634523/", excerpt: "We demonstrated that ventilation prior to cord clamping markedly improves cardiovascular function by increasing pulmonary blood flow before the cord is clamped, thus further stabilising the cerebral haemodynamic transition." },
    { label: "Am Zool 1992", citation: "Faber JJ, Thornburg KLR, Binder ND. Physiology of Placental Transfer in Mammals. Am Zool. 1992;32(2):339-354.", url: "https://doi.org/10.1093/icb/32.2.339", excerpt: "Almost all substances that are passively transferred fall into two classes. Their transfer is either purely 'flow limited' or purely 'diffusion limited'... Transfer of oxygen is flow limited or nearly so." },
    { label: "Serov et al. 2015", citation: "Serov AS, Salafia CM, Filoche M, Grebenkov DS. Analytical theory of oxygen transport in the human placenta. J Theor Biol. 2015;368:133-144.", url: "https://doi.org/10.1016/j.jtbi.2014.12.016", excerpt: "Only two geometrical characteristics of a placental cross section, villi density and the effective villi radius, are needed to predict fetal oxygen uptake." },
    { label: "Pediatr Res 2023", citation: "Chakkarapani AA, Roehr CC, Hooper SB, et al. Transitional circulation and hemodynamic monitoring in newborn infants. Pediatric Research. 2024;96:595–603. Published online 2 January 2023. Bibliographic identity checked; the previously recorded excerpt still requires verbatim original-document verification.", url: "https://doi.org/10.1038/s41390-022-02427-8", excerpt: "Lung aeration triggers a significant decrease in pulmonary vascular resistance, consequently increasing pulmonary blood flow and cardiac venous return." },
    { label: "Karger 2014", citation: "van Vonderen JJ, Roest AA, Siew ML, et al. Measuring Physiological Changes during the Transition to Life after Birth. Neonatology. 2014;105(3):230-242.", url: "https://doi.org/10.1159/000356704", excerpt: "Clamping the umbilical cord also contributes to these hemodynamic changes by altering the cardiac preload and increasing peripheral systemic vascular resistance." },
    { label: "Bentley et al. 2021", citation: "Bentley RET, Hindmarch CCT, Dunham-Snary KJ, et al. The molecular mechanisms of oxygen-sensing in human ductus arteriosus smooth muscle cells. Genomics. 2021;113(5):3128-3140.", url: "https://doi.org/10.1016/j.ygeno.2021.07.006", excerpt: "DA smooth muscle cells sense the rise in PaO2 via a mitochondrial-redox mechanism, leading to calcium influx and constriction." },
    { label: "NCBI Bookshelf 2016", citation: "Yokoyama U, Minamisawa S, Ishikawa Y. The Multiple Roles of Prostaglandin E2 in the Regulation of the Ductus Arteriosus. In: Etiology and Morphogenesis of Congenital Heart Disease. Springer; 2016.", url: "https://www.ncbi.nlm.nih.gov/books/NBK500295/", excerpt: "Prostaglandin E2 (PGE2) dilates the DA through activation of its receptor EP4... oxygen constricts the DA by inhibiting potassium channels." },
    { label: "BJA Educ 2015", citation: "Morton SU, Bhatt D. Neonatal physiology and the transitional circulation. BJA Education. 2016;16(4):106-112.", url: "https://doi.org/10.1093/bjaed/mkv047" },
    { label: "Power & Kam Ch.18", citation: "Power I, Kam P. Principles of Physiology for the Anaesthetist. 3rd ed. Chapter 18: Foetal and Neonatal Physiology." },
    { label: "Ganong Ch.33", citation: "Barrett KE et al. Ganong's Review of Medical Physiology. 26th ed. Chapter 33: Foetal and Neonatal Circulation." },
    { label: "BJA Educ Neonatal CHD", citation: "Sarkar M, Prabhu V. Basics of paediatric anaesthesia for congenital heart disease. BJA Education. 2017;17(10):341-347.", url: "https://doi.org/10.1093/bjaed/mkx033", excerpt: "Prostaglandin E1 is used to maintain ductal patency in neonates with duct-dependent pulmonary or systemic blood flow until definitive treatment can be undertaken." },
  ],
