  "toxicology": [
    { label: "SNAP 2014", citation: "Bateman DN, Dear JW, Thanacoody HKR, et al. Reduction of adverse effects from intravenous acetylcysteine treatment for paracetamol poisoning: a randomised controlled trial. Lancet. 2014;383(9918):697-704.", url: "https://doi.org/10.1016/S0140-6736(13)62062-0" },
    { label: "Boyer 2012", citation: "Boyer EW. Management of opioid analgesic overdose. N Engl J Med. 2012;367(2):146-155.", url: "https://doi.org/10.1056/NEJMra1202561" },
    { label: "Anaesthesia 2023 LAST Review", citation: "Management of severe local anaesthetic toxicity: a narrative review and clinical update. Anaesthesia. 2023 — lipid emulsion infusion 15 ml/kg/h for all patients, doubled if the circulation remains unstable.", url: "https://associationofanaesthetists-publications.onlinelibrary.wiley.com/doi/10.1111/anae.16091" },
    { label: "BJA Educ Poisoning 2016", citation: "Management of the acutely poisoned patient. BJA Education. 2016;16(7):218-224.", url: "https://academic.oup.com/bjaed/article/16/7/218/2364883" },
    { label: "MHRA NAC 2012", citation: "Medicines and Healthcare products Regulatory Agency. Intravenous N-acetylcysteine: new weight-based dosing regimens to reduce the risk of errors. Drug Safety Update.", url: "https://www.gov.uk/drug-safety-update/intravenous-n-acetylcysteine-new-weight-based-dosing-regimens-to-reduce-the-risk-of-errors" },
    { label: "AoA LAST 2023", citation: "Association of Anaesthetists. Management of severe local anaesthetic systemic toxicity. 2023 — lipid emulsion 20% 1.5 ml/kg bolus then infusion 15 ml/kg/h, doubled to 30 ml/kg/h if circulation remains unstable.", url: "https://anaesthetists.org/Home/Resources-publications/Guidelines/Management-of-severe-local-anaesthetic-systemic-toxicity-2023" },
    { label: "NPIS Toxbase", citation: "National Poisons Information Service. TOXBASE Clinical Toxicology Database.", url: "https://www.toxbase.org" },
    { label: "BJA Educ 2016", citation: "Bradberry SM, et al. Management of the acutely poisoned patient. BJA Education. 2016;16(7):218-225.", url: "https://doi.org/10.1093/bjaed/mkv054" },
    { label: "AAGBI Lipid Rescue", citation: "Association of Anaesthetists. Management of Severe Local Anaesthetic Toxicity. 2010 (updated 2023).", url: "https://anaesthetists.org/Home/Resources-publications/Guidelines/Management-of-severe-local-anaesthetic-toxicity" },
    { label: "BJA Educ 2021 Cardiotox", citation: "Coppens M, et al. Management of cardiovascular drug toxicity. BJA Education. 2021;21(5):190-197. High-dose insulin euglycaemia therapy: 1 unit/kg short-acting insulin bolus followed by 0.5–2 units/kg/h with dextrose to maintain euglycaemia and close potassium monitoring.", url: "https://doi.org/10.1016/j.bjae.2021.01.004", excerpt: "High-dose insulin euglycaemia (HIET) has emerged as a key therapy in CCB poisoning, and may be considered first line. Proposed mechanisms include a direct inotropic effect and improved myocardial carbohydrate metabolism... A typical regimen is 1 unit kg-1 of a short-acting insulin, followed by an infusion of 0.5–2 units kg-1 h-1. Dextrose is infused to maintain euglycaemia and potassium is monitored closely." },
    { label: "EXTRIP Theophylline", citation: "Ghannoum M, Wiegand TJ, Liu KD, et al. Extracorporeal treatment for theophylline poisoning: systematic review and recommendations from the EXTRIP workgroup. Clin Toxicol. 2015;53(4):215-229.", url: "https://doi.org/10.3109/15563650.2015.1014907", excerpt: "Charcoal haemoperfusion is more effective than haemodialysis for the removal of theophylline, and should be used if available. The EXTRIP workgroup recommend extracorporeal removal in severe theophylline poisoning with seizures, life-threatening ventricular arrhythmias, or refractory hypotension." },
    { label: "EXTRIP Salicylate 2015", citation: "Juurlink DN, Gosselin S, Kielstein JT, et al. Extracorporeal treatment for salicylate poisoning: systematic review and recommendations from the EXTRIP workgroup. Ann Emerg Med. 2015;66(2):165-181.", url: "https://doi.org/10.1016/j.annemergmed.2015.03.031" },
  ],
